	@Test
	void valuesNameBindingEstimatesDerivedAssemblyPartOfSurface(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc,posc");
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();

		try {
			loadSyntheticEngineeringAssemblies(repository);
			LmdbPlannerAwait.rebuildSketchesIfEnabled(store);

			BindingSetAssignment assemblyNames = assemblyNameBindings();
			StatementPattern name = new StatementPattern(Var.of("assembly"), Var.of("namePredicate", ENG_NAME),
					Var.of("assemblyName"));
			StatementPattern type = new StatementPattern(Var.of("assembly"), Var.of("rdfType", RDF_TYPE),
					Var.of("assemblyType", ENG_ASSEMBLY));
			StatementPattern partOf = new StatementPattern(Var.of("component"), Var.of("partOfPredicate", ENG_PART_OF),
					Var.of("assembly"));
			assertDirectFiniteDerivedPartOfSurface(store, assemblyNames, name, type, partOf);

			TupleExpr join = new Join(new Join(new Join(assemblyNames, name), type), partOf);
			EvaluationStatistics statistics = store.getBackingStore().getEvaluationStatistics();
			CascadesPlan plan = new LmdbCascadesOptimizer(statistics, false)
					.planPreparedInput(join, OptimizationGoal.root(join, PhysicalProperties.ANY));

			StatementPattern plannedPartOf = findStatementPattern(plan.tupleExpr(), ENG_PART_OF, "assembly");
			assertTrue(plannedPartOf != null, "Expected planned partOf lookup. plan=" + plan.tupleExpr());

			double expectedSurfaceRows = ASSEMBLY_COUNT * COMPONENTS_PER_ASSEMBLY;
			double plannedAccessRows = plannedPartOf.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_ACCESS_ROWS);
			double plannedInvocations = plannedPartOf.getDoubleMetricPlanned("plannedRepeatedInvocations");
			double plannedWorkRows = plannedPartOf.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS);
			double plannedSequentialRows = plannedPartOf.getDoubleMetricPlanned("plannedCostSequentialRows");
			double plannedResultRows = plannedPartOf.getDoubleMetricPlanned("plannedCostResultRows");
			boolean hashJoin = "hash".equals(
					plan.tupleExpr().getStringMetricPlanned("optimizer.joinAlgorithmHint"));
			if (hashJoin) {
				assertEquals(expectedSurfaceRows, plannedAccessRows, expectedSurfaceRows * 0.25d,
						"A hash join should scan the bounded partOf surface exactly once. expectedAccessRows="
								+ expectedSurfaceRows + ", metrics=" + plannedPartOf + ", plan=" + plan.tupleExpr());
				assertEquals(1.0d, plannedInvocations, 0.01d,
						"A hash join should build its independent right input once. metrics=" + plannedPartOf
								+ ", plan=" + plan.tupleExpr());
			} else {
				assertEquals(COMPONENTS_PER_ASSEMBLY, plannedAccessRows, COMPONENTS_PER_ASSEMBLY * 0.25d,
						"The VALUES-derived ?assembly surface should keep the partOf lookup on a single-assembly "
								+ "access path while repeated invocations account for the finite branches. "
								+ "expectedAccessRows=" + COMPONENTS_PER_ASSEMBLY
								+ ", doubleMetrics=" + plannedPartOf.getDoubleMetricsPlanned()
								+ ", stringMetrics=" + plannedPartOf.getStringMetricsPlanned()
								+ ", metrics=" + plannedPartOf + ", joins=" + joinMetrics(plan.tupleExpr())
								+ ", plan=" + plan.tupleExpr());
				assertTrue(plannedInvocations >= 1.0d && plannedInvocations <= ASSEMBLY_COUNT * 2.0d,
						"The partOf lookup should be repeated once per finite assembly rather than once per broad "
								+ "name row. expectedInvocations=" + ASSEMBLY_COUNT + ", metrics=" + plannedPartOf
								+ ", plan=" + plan.tupleExpr());
			}
			assertEquals(expectedSurfaceRows, plan.tupleExpr().getResultSizeEstimate(), expectedSurfaceRows * 0.25d,
					"Both join implementations must retain the complete VALUES-derived partOf cardinality. plan="
							+ plan.tupleExpr() + ", partOfDoubleMetrics="
							+ plannedPartOf.getDoubleMetricsPlanned() + ", partOfStringMetrics="
							+ plannedPartOf.getStringMetricsPlanned() + ", joinMetrics="
							+ joinMetrics(plan.tupleExpr()));
			assertEquals(expectedSurfaceRows, plannedSequentialRows, expectedSurfaceRows * 0.25d,
					"Both join implementations should retain the same bounded partOf scan work. "
							+ "expectedSurfaceRows=" + expectedSurfaceRows + ", metrics=" + plannedPartOf
							+ ", plan=" + plan.tupleExpr());
			assertEquals(expectedSurfaceRows, plannedResultRows, expectedSurfaceRows * 0.25d,
					"Both join implementations should retain the same bounded partOf result work. "
							+ "expectedSurfaceRows=" + expectedSurfaceRows + ", metrics=" + plannedPartOf
							+ ", plan=" + plan.tupleExpr());
			assertTrue(plannedWorkRows >= plannedSequentialRows + plannedResultRows,
					"Total physical work should include both access and result work. plannedWorkRows="
							+ plannedWorkRows + ", plannedSequentialRows=" + plannedSequentialRows
							+ ", plannedResultRows=" + plannedResultRows + ", metrics=" + plannedPartOf
							+ ", plan=" + plan.tupleExpr());
		} finally {
			repository.shutDown();
		}
	}

	private static List<String> joinMetrics(TupleExpr expression) {
		List<String> metrics = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Join join) {
				metrics.add("rows=" + join.getResultSizeEstimate() + ", doubles="
						+ join.getDoubleMetricsPlanned() + ", strings=" + join.getStringMetricsPlanned());
				super.meet(join);
			}
		});
		return metrics;
	}

	@Test
	void generatedRareLiteralEstimateNeverExceedsPredicateScan(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc,posc");
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();

		try {
			loadSyntheticEngineeringAssemblies(repository);
			LmdbPlannerAwait.rebuildSketchesIfEnabled(store);

			EvaluationStatistics statistics = store.getBackingStore().getEvaluationStatistics();
			StatementPattern predicateScan = new StatementPattern(Var.of("assembly"),
					Var.of("namePredicate", ENG_NAME), Var.of("assemblyName"));
			StatementPattern rareLiteralLookup = new StatementPattern(Var.of("assembly"),
					Var.of("namePredicate", ENG_NAME), Var.of("assemblyName", VF.createLiteral("Assembly 1")));

			double scanRows = statistics.getCardinality(predicateScan);
			double literalRows = statistics.getCardinality(rareLiteralLookup);
			assertTrue(Double.isFinite(scanRows) && scanRows >= ASSEMBLY_COUNT,
					"The generated name predicate scan should expose a finite base surface. scanRows=" + scanRows
							+ ", literalRows=" + literalRows);
			assertTrue(Double.isFinite(literalRows) && literalRows > 0.0d,
					"The generated rare literal lookup should have positive finite evidence. scanRows=" + scanRows
							+ ", literalRows=" + literalRows);
			assertTrue(literalRows <= scanRows,
					"A fixed object literal must never estimate more rows than scanning the same predicate. scanRows="
							+ scanRows + ", literalRows=" + literalRows);
			assertTrue(literalRows <= ASSEMBLY_COUNT * 2.0d,
					"The rare generated literal should stay near its observed singleton surface. scanRows=" + scanRows
							+ ", literalRows=" + literalRows);
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void cascadesConnectedPlannerUsesFinitePrefixValuesForObjectLookup(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc,posc");
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();

		try {
			loadSyntheticLibraryBranches(repository);
			LmdbPlannerAwait.rebuildSketchesIfEnabled(store);
			BindingSetAssignment branchNames = branchNameBindings();
			StatementPattern name = new StatementPattern(Var.of("branch"), Var.of("namePredicate", LIB_NAME),
					Var.of("branchName"));
			TupleExpr join = new Join(branchNames, name);

			EvaluationStatistics statistics = store.getBackingStore().getEvaluationStatistics();
			JoinFactorCostModel costModel = (JoinFactorCostModel) statistics;
			CascadesPlan plan = new LmdbCascadesOptimizer(statistics, false)
					.planPreparedInput(join, OptimizationGoal.root(join, PhysicalProperties.ANY));
			StatementPattern plannedName = findStatementPattern(plan.tupleExpr(), LIB_NAME, "branchName");
			assertTrue(plannedName != null, "Expected planned library name lookup. plan=" + plan.tupleExpr());

			double plannedRows = plannedName.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_CARDINALITY_ROWS);
			assertTrue(plannedRows <= 2.0d,
					"The connected Cascades planner should pass finite prefix values into object lookups instead of "
							+ "costing the selected names by global predicate fanout. plannedRows=" + plannedRows
							+ ", metrics=" + plannedName);
			assertFiniteLookupSource(plannedName,
					"A statement evaluated over concrete VALUES rows must retain finite-domain provenance");
			assertEquals(2.0d, plannedName.getDoubleMetricPlanned("plannedRepeatedInvocations"), 0.0d,
					"Bag multiplicity requires one lookup invocation for each VALUES row");
			assertEquals(2.0d, plannedName.getDoubleMetricPlanned("plannedDistinctLookupBindings"), 0.0d,
					"The two distinct VALUES terms require two distinct concrete probes");
			assertEquals("[P, O]",
					plannedName.getStringMetricPlanned(TelemetryMetricNames.PLANNED_LOOKUP_COMPONENTS),
					"The finite object values must produce a predicate/object lookup");
		} finally {
			repository.shutDown();
		}
	}

